CREATE OR REPLACE FUNCTION public.validate_profile_fields() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.full_name IS DISTINCT FROM OLD.full_name THEN IF length(trim(NEW.full_name)) NOT BETWEEN 1 AND 100 OR length(NEW.full_name)>100 THEN RAISE EXCEPTION 'Name must contain 1 to 100 characters'; END IF; NEW.full_name:=trim(NEW.full_name); END IF; IF NEW.avatar_url IS NOT NULL AND (split_part(NEW.avatar_url,'/',1)<>NEW.id::text OR NEW.avatar_url !~ '^[a-zA-Z0-9_/-]+\.(png|jpg|jpeg|webp)$') THEN RAISE EXCEPTION 'Invalid avatar path'; END IF; IF auth.uid() IS NOT NULL AND NEW.email IS DISTINCT FROM OLD.email THEN RAISE EXCEPTION 'Account email cannot be changed through profile settings'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.validate_profile_fields() FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.add_workspace_member_by_email(_workspace_id uuid,_email text,_role public.app_role) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE target uuid; BEGIN IF NOT public.has_role(auth.uid(),'admin',_workspace_id) THEN RAISE EXCEPTION 'Only workspace administrators can manage members'; END IF; SELECT u.id INTO target FROM auth.users u JOIN public.profiles p ON p.id=u.id WHERE lower(u.email)=lower(trim(_email)) AND u.email_confirmed_at IS NOT NULL; IF target IS NULL THEN RAISE EXCEPTION 'No confirmed account found; ask the user to sign up and confirm their email first'; END IF; PERFORM public.manage_workspace_member(_workspace_id,target,_role); END $$;
REVOKE ALL ON FUNCTION public.add_workspace_member_by_email(uuid,text,public.app_role) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.add_workspace_member_by_email(uuid,text,public.app_role) TO authenticated;